(window.__quranSurahs=window.__quranSurahs||{})[97]={"nomPhon":"Al-Qadr","versets":{"1":{"text":"Nous l'avons certes, fait descendre (le Coran) pendant la nuit d'Al-Qadr.","arabe":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ"},"2":{"text":"Et qui te dira ce qu'est la nuit d'Al-Qadr?","arabe":"وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ"},"3":{"text":"La nuit d'Al-Qadr est meilleure que mille mois.","arabe":"لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ"},"4":{"text":"Durant celle-ci descendent les Anges ainsi que l'Esprit, par permission de leur Seigneur pour tout ordre.","arabe":"تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ"},"5":{"text":"Elle est paix et salut jusqu'à l'apparition de l'aube.","arabe":"سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ"}}};